/*
 * Lotties: Progressive Web App manifests (AGPL-3.0-or-later).
 *
 * The web manifest has no dark icon field, so the app ships two: `manifest.webmanifest` (light
 * icons, light scheme colours; generated by VitePWA) and `manifest-dark.webmanifest` (dark icons,
 * dark scheme colours; emitted by `darkManifestPlugin`). They share every other member. Which one
 * the page links is chosen at run time by public/theme-init.js (and src/theme/AppThemeProvider.tsx
 * when the user switches the theme), see src/pwa/schemeLinks.ts.
 */
import type { Plugin } from 'vite';
import { DARK, LIGHT } from './src/theme/tokens';

export const DARK_MANIFEST_FILE = 'manifest-dark.webmanifest';

export interface ManifestIcon {
  src: string;
  sizes: string;
  type: string;
  purpose: 'any' | 'maskable' | 'monochrome';
}

export interface AppManifest {
  id: string;
  name: string;
  short_name: string;
  description: string;
  lang: string;
  start_url: string;
  scope: string;
  display: 'standalone';
  orientation: 'portrait';
  theme_color: string;
  background_color: string;
  icons: ManifestIcon[];
}

const png = (src: string, size: number, purpose: ManifestIcon['purpose']): ManifestIcon => ({
  src,
  sizes: `${size}x${size}`,
  type: 'image/png',
  purpose,
});

// Only alpha is used, so the monochrome icon is shared by both manifests.
const MONOCHROME = png('/icon-monochrome-512.png', 512, 'monochrome');

const COMMON = {
  // Explicit, so both manifests are the same app (one install) whichever one the page links.
  id: '/',
  name: 'Lotties',
  short_name: 'Lotties',
  description: 'Track baby events offline, share with a co-parent, and see routine predictions.',
  lang: 'en',
  start_url: '/',
  scope: '/',
  display: 'standalone',
  orientation: 'portrait',
} as const;

export const LIGHT_MANIFEST: AppManifest = {
  ...COMMON,
  theme_color: LIGHT.themeColor,
  background_color: LIGHT.background,
  icons: [
    png('/icon-192.png', 192, 'any'),
    png('/icon-512.png', 512, 'any'),
    png('/icon-maskable-512.png', 512, 'maskable'),
    MONOCHROME,
  ],
};

export const DARK_MANIFEST: AppManifest = {
  ...COMMON,
  theme_color: DARK.themeColor,
  background_color: DARK.background,
  icons: [
    png('/icon-dark-192.png', 192, 'any'),
    png('/icon-dark-512.png', 512, 'any'),
    png('/icon-maskable-dark-512.png', 512, 'maskable'),
    MONOCHROME,
  ],
};

/** Emits the dark manifest next to the one VitePWA generates; served by the dev server too. */
export function darkManifestPlugin(): Plugin {
  const json = () => `${JSON.stringify(DARK_MANIFEST, null, 2)}\n`;
  return {
    name: 'baby-routine:dark-manifest',
    enforce: 'post',
    configureServer(server) {
      server.middlewares.use(`/${DARK_MANIFEST_FILE}`, (_req, res) => {
        res.setHeader('Content-Type', 'application/manifest+json');
        res.end(json());
      });
    },
    // index.html carries its own manifest link (theme-init.js needs it before the head ends);
    // drop the second one VitePWA appends.
    transformIndexHtml: {
      order: 'post',
      handler(html) {
        let seen = false;
        return html.replace(/<link rel="manifest"[^>]*>/g, (tag) => {
          if (seen) return '';
          seen = true;
          return tag;
        });
      },
    },
    generateBundle() {
      this.emitFile({ type: 'asset', fileName: DARK_MANIFEST_FILE, source: json() });
    },
  };
}
